-- Dataset: Disbursement Trend
-- Page: Sales and Funnel
-- Connection: CREDIT_PORTFOLIO | Mode: Direct
-- Parameters: p_date_key = October 2026 (Text), p_product_id = All Products (Text), p_region_id = All Regions (Text), p_channel_id = All Channels (Text)

WITH bounds AS (SELECT (SELECT calendar_date FROM credit.calendar CROSS JOIN credit.dataset_run
 WHERE calendar_date=month_end AND to_char(calendar_date,'YYYYMMDD')::integer=${IF(p_date_key="October 2026",20261031,IF(p_date_key="September 2026",20260930,IF(p_date_key="August 2026",20260831,IF(p_date_key="July 2026",20260731,IF(p_date_key="June 2026",20260630,IF(p_date_key="May 2026",20260531,IF(p_date_key="April 2026",20260430,IF(p_date_key="March 2026",20260331,IF(p_date_key="February 2026",20260228,IF(p_date_key="January 2026",20260131,IF(p_date_key="December 2025",20251231,IF(p_date_key="November 2025",20251130,IF(p_date_key="October 2025",20251031,IF(p_date_key="September 2025",20250930,IF(p_date_key="August 2025",20250831,IF(p_date_key="July 2025",20250731,IF(p_date_key="June 2025",20250630,IF(p_date_key="May 2025",20250531,IF(p_date_key="April 2025",20250430,IF(p_date_key="March 2025",20250331,IF(p_date_key="February 2025",20250228,IF(p_date_key="January 2025",20250131,IF(p_date_key="December 2024",20241231,IF(p_date_key="November 2024",20241130,INT(p_date_key)))))))))))))))))))))))))}
 AND calendar_date BETWEEN report_start AND as_of_date) as_of_date),loans AS (
      SELECT l.* FROM credit.v_loan_dimension l CROSS JOIN bounds d
      WHERE l.issue_date BETWEEN '2024-11-01'::date AND d.as_of_date AND (${IF(p_product_id="All Products",0,IF(p_product_id="Personal Loan",1,IF(p_product_id="Auto Loan",2,IF(p_product_id="Mortgage",3,INT(p_product_id)))))}=0 OR l.product_id=${IF(p_product_id="All Products",0,IF(p_product_id="Personal Loan",1,IF(p_product_id="Auto Loan",2,IF(p_product_id="Mortgage",3,INT(p_product_id)))))}) AND (${IF(p_region_id="All Regions",0,IF(p_region_id="Moscow",1,IF(p_region_id="Saint Petersburg",2,IF(p_region_id="Tatarstan",3,IF(p_region_id="Sverdlovsk Region",4,IF(p_region_id="Krasnodar Region",5,IF(p_region_id="Novosibirsk Region",6,INT(p_region_id))))))))}=0 OR l.region_id=${IF(p_region_id="All Regions",0,IF(p_region_id="Moscow",1,IF(p_region_id="Saint Petersburg",2,IF(p_region_id="Tatarstan",3,IF(p_region_id="Sverdlovsk Region",4,IF(p_region_id="Krasnodar Region",5,IF(p_region_id="Novosibirsk Region",6,INT(p_region_id))))))))}) AND (${IF(p_channel_id="All Channels",0,IF(p_channel_id="Branch",1,IF(p_channel_id="Online",2,IF(p_channel_id="Mobile App",3,IF(p_channel_id="Partner",4,INT(p_channel_id))))))}=0 OR l.channel_id=${IF(p_channel_id="All Channels",0,IF(p_channel_id="Branch",1,IF(p_channel_id="Online",2,IF(p_channel_id="Mobile App",3,IF(p_channel_id="Partner",4,INT(p_channel_id))))))})),
      monthly AS (SELECT date_trunc('month',issue_date)::date month_start,sum(original_principal) amount FROM loans GROUP BY 1)
      SELECT c.calendar_date AS month_end,to_char(c.calendar_date,'Mon YY') label,
      'Disbursements'::text series,coalesce(m.amount,0)/1000000 AS value
      FROM credit.calendar c CROSS JOIN bounds d LEFT JOIN monthly m ON m.month_start=c.month_start
      WHERE c.calendar_date=c.month_end AND c.calendar_date BETWEEN '2024-11-01'::date AND d.as_of_date
      AND EXISTS(SELECT 1 FROM loans) ORDER BY c.calendar_date
